// NorthAmerica regional land mask — baked from Natural Earth via tools/geodata-poc/bake-regional-mask.mjs.
import { createRegionalMask } from "./regional-mask";

export const NORTH_AMERICA_LON_MIN = -168;
export const NORTH_AMERICA_LON_MAX = -52;
export const NORTH_AMERICA_LAT_MIN = 12;
export const NORTH_AMERICA_LAT_MAX = 72;
export const NORTH_AMERICA_MASK_COLS = 116;
export const NORTH_AMERICA_MASK_ROWS = 64;

const northAmericaMask = createRegionalMask({
  lonMin: NORTH_AMERICA_LON_MIN,
  lonMax: NORTH_AMERICA_LON_MAX,
  latMin: NORTH_AMERICA_LAT_MIN,
  latMax: NORTH_AMERICA_LAT_MAX,
  maskCols: NORTH_AMERICA_MASK_COLS,
  maskRows: NORTH_AMERICA_MASK_ROWS,
  maskB64:
    "",
});

export const isNorthAmericaLand = northAmericaMask.isLand.bind(northAmericaMask);
export const northAmericaTileLatLon = northAmericaMask.tileLatLon.bind(northAmericaMask);
